def fire_load_density(total_fire_load_mj, floor_area):
    if floor_area == 0.0:
        return 0.0
    return total_fire_load_mj / floor_area






def heat_release_rate(mass_loss_rate, heat_of_combustion):
    return mass_loss_rate * heat_of_combustion






def flashover_mfo(area_vent, height_vent, area_total):
    return 750.0 * area_vent * math.sqrt(height_vent) + 378.0 * area_total






def sprinkler_activation_time(rti, gas_temp, ambient_temp, velocity):
    if velocity <= 0.0:
        return 0.0
    return rti / math.sqrt(velocity)






def smoke_layer_height(ceiling_height, time_s, hrr):
    if ceiling_height == 0.0:
        return 0.0
    descent = 0.1 * math.sqrt(hrr) * math.sqrt(time_s) / ceiling_height
    z = ceiling_height - descent
    if z < 0.0:
        return 0.0
    return z






def evacuation_time(population, exit_width, flow_rate):
    denom = exit_width * flow_rate
    if denom == 0.0:
        return 0.0
    return population / denom






def safe_egress_time(detection, alarm, pre_movement, travel):
    return detection + alarm + pre_movement + travel






def fire_resistance_rating(thickness_mm, material_factor):
    return thickness_mm * material_factor






def ventilation_factor(area_opening, height_opening):
    return area_opening * math.sqrt(height_opening)






def fire_severity(fire_load, vent_factor):
    if vent_factor == 0.0:
        return 0.0
    return fire_load / vent_factor






def co_concentration_danger(ppm):
    if ppm > 200.0:
        return 2
    if ppm >= 35.0:
        return 1
    return 0






def occupant_load(floor_area, occupant_factor):
    if occupant_factor == 0.0:
        return 0.0
    return floor_area / occupant_factor
